 (function () {
   'use strict';

   /* ---- Promo banner dismiss ---- */
   const banner = document.querySelector('.promo-banner');
   const dismissBtn = document.querySelector('.promo-dismiss');
   if (banner && dismissBtn) {
     dismissBtn.addEventListener('click', function () {
       banner.hidden = true;
     });
   }

   /* ---- Newsletter form ---- */
   const form = document.querySelector('.newsletter-form');
   const statusEl = document.querySelector('.newsletter-status');
   if (form && statusEl) {
     form.addEventListener('submit', function (e) {
       e.preventDefault();
       const emailInput = form.querySelector('#email-input');
       const value = emailInput ? emailInput.value.trim() : '';
       if (!value || !/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(value)) {
         statusEl.textContent = 'Please enter a valid email address.';
         if (emailInput) {
           emailInput.setAttribute('aria-invalid', 'true');
           emailInput.setAttribute('aria-describedby', 'email-hint email-error');
           let errEl = document.getElementById('email-error');
           if (!errEl) {
             errEl = document.createElement('p');
             errEl.id = 'email-error';
             errEl.className = 'sr-only';
             errEl.setAttribute('aria-live', 'assertive');
             emailInput.parentNode.appendChild(errEl);
           }
           errEl.textContent = 'Please enter a valid email address.';
           emailInput.focus();
         }
         return;
       }
       // Success
       if (emailInput) {
         emailInput.removeAttribute('aria-invalid');
         emailInput.setAttribute('aria-describedby', 'email-hint');
         const errEl = document.getElementById('email-error');
         if (errEl) errEl.textContent = '';
       }
       statusEl.textContent = 'Thanks! You\'re subscribed.';
       form.reset();
     });
   }

   /* ---- "Add to cart" feedback ---- */
   document.querySelectorAll('.product-grid .btn-sm, .deals-section .btn').forEach(function (btn) {
     btn.addEventListener('click', function () {
       const cartLabel = document.querySelector('.cart-btn');
       if (!cartLabel) return;
       // Update the live cart count (aria-label update keeps AT informed)
       const countEl = cartLabel.querySelector('.cart-count');
       const current = parseInt(countEl ? countEl.textContent : '0', 10) || 0;
       const next = current + 1;
       if (countEl) countEl.textContent = next;
       cartLabel.setAttribute('aria-label', 'Cart, ' + next + ' item' + (next === 1 ? '' : 's'));
     });
   });
 })();

