2.    LUMINA SHOP — styles.css
3.    Modern, clean retail design • WCAG 2.2 AA
4.    ============================================================ */
5. 
6. /* ---- Reset / base ---- */
7. *, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }
8. 
9. :root {
10.   --color-brand:       #6C63FF;
11.   --color-brand-dark:  #4a42d0;
12.   --color-brand-light: #ede9ff;
13.   --color-text:        #1a1a2e;
14.   --color-text-muted:  #5a5a7a;
15.   --color-bg:          #ffffff;
16.   --color-surface:     #f7f7fb;
17.   --color-border:      #e2e2ec;
18.   --color-success:     #17705e;
19.   --color-error:       #c0392b;
20.   --color-deal-rose:   #fce4ec;
21.   --color-deal-teal:   #e0f7f5;
22.   --color-deal-indigo: #ede9ff;
23.   --radius-sm:  6px;
24.   --radius-md:  12px;
25.   --radius-lg:  20px;
26.   --shadow-sm:  0 1px 4px rgba(0,0,0,.08);
27.   --shadow-md:  0 4px 16px rgba(0,0,0,.10);
28.   --shadow-lg:  0 8px 32px rgba(0,0,0,.12);
29.   --font-sans:  'Segoe UI', system-ui, -apple-system, sans-serif;
30.   --transition: 200ms ease;
31.   --max-width:  1200px;
32. }
33. 
34. html { font-size: 16px; scroll-behavior: smooth; }
35. 
36. body {
37.   font-family: var(--font-sans);
38.   color: var(--color-text);
39.   background: var(--color-bg);
40.   line-height: 1.6;
41.   -webkit-font-smoothing: antialiased;
42. }
43. 
44. /* ---- Utility ---- */
45. .sr-only {
46.   position: absolute;
47.   width: 1px; height: 1px;
48.   padding: 0; margin: -1px;
49.   overflow: hidden;
50.   clip: rect(0,0,0,0);
51.   white-space: nowrap;
52.   border: 0;
53. }
54. 
55. /* ---- Skip link ---- */
56. .skip-link {
57.   position: absolute;
58.   top: -3rem;
59.   left: 1rem;
60.   padding: .6rem 1.2rem;
61.   background: var(--color-brand);
62.   color: #fff;
63.   border-radius: var(--radius-sm);
64.   font-weight: 600;
65.   text-decoration: none;
66.   z-index: 9999;
67.   transition: top var(--transition);
68. }
69. .skip-link:focus { top: 1rem; }
70. 
71. /* ---- Focus ring ---- */
72. :focus-visible {
73.   outline: 3px solid var(--color-brand);
74.   outline-offset: 3px;
75.   border-radius: 2px;
76. }
77. /* Remove default for non-keyboard */
78. :focus:not(:focus-visible) { outline: none; }
79. 
80. /* ============================================================
81.    HEADER
82.    ============================================================ */
83. .site-header {
84.   position: sticky;
85.   top: 0;
86.   z-index: 100;
87.   background: rgba(255,255,255,.92);
88.   backdrop-filter: blur(12px);
89.   border-bottom: 1px solid var(--color-border);
90. }
91. .header-inner {
92.   max-width: var(--max-width);
93.   margin: 0 auto;
94.   padding: 0 1.5rem;
95.   height: 64px;
96.   display: flex;
97.   align-items: center;
98.   gap: 2rem;
99. }
100. 
101. /* Logo */
102. .logo {
103.   display: flex;
104.   align-items: center;
105.   gap: .5rem;
106.   text-decoration: none;
107.   color: var(--color-text);
108.   font-weight: 700;
109.   font-size: 1.2rem;
110.   flex-shrink: 0;
111. }
112. .logo--footer { color: #fff; }
113. 
114. /* Primary nav */
115. .nav-list {
116.   display: flex;
117.   list-style: none;
118.   gap: .25rem;
119.   flex: 1;
120. }
121. .nav-list a {
122.   display: block;
123.   padding: .4rem .75rem;
124.   text-decoration: none;
125.   color: var(--color-text-muted);
126.   font-size: .9rem;
127.   font-weight: 500;
128.   border-radius: var(--radius-sm);
129.   transition: color var(--transition), background var(--transition);
130. }
131. .nav-list a:hover,
132. .nav-list a:focus-visible { color: var(--color-brand); background: var(--color-brand-light); }
133. .nav-list a[aria-current="page"] {
134.   color: var(--color-brand);
135.   background: var(--color-brand-light);
136.   text-decoration: underline;
137. }
138. 
139. /* Header actions */
140. .header-actions { display: flex; align-items: center; gap: .5rem; margin-left: auto; }
141. 
142. .icon-btn {
143.   position: relative;
144.   display: flex;
145.   align-items: center;
146.   justify-content: center;
147.   width: 40px; height: 40px;
148.   background: transparent;
149.   border: none;
150.   border-radius: var(--radius-sm);
151.   color: var(--color-text);
152.   cursor: pointer;
153.   transition: background var(--transition), color var(--transition);
154. }
155. .icon-btn:hover { background: var(--color-surface); color: var(--color-brand); }
156. 
157. .cart-count {
158.   position: absolute;
159.   top: 4px; right: 4px;
160.   width: 16px; height: 16px;
161.   background: var(--color-brand);
162.   color: #fff;
163.   font-size: .65rem;
164.   font-weight: 700;
165.   border-radius: 50%;
166.   display: flex; align-items: center; justify-content: center;
167. }
168. 
169. /* ============================================================
170.    BUTTONS
171.    ============================================================ */
172. .btn {
173.   display: inline-flex;
174.   align-items: center;
175.   justify-content: center;
176.   gap: .4rem;
177.   padding: .65rem 1.4rem;
178.   border-radius: var(--radius-sm);
179.   font-size: .9rem;
180.   font-weight: 600;
181.   text-decoration: none;
182.   border: 2px solid transparent;
183.   cursor: pointer;
184.   transition: background var(--transition), color var(--transition), border-color var(--transition), transform var(--transition);
185.   white-space: nowrap;
186. }
187. .btn:active { transform: scale(.97); }
188. 
189. .btn-primary {
190.   background: var(--color-brand);
191.   color: #fff;
192.   border-color: var(--color-brand);
193. }
194. .btn-primary:hover, .btn-primary:focus-visible {
195.   background: var(--color-brand-dark);
196.   border-color: var(--color-brand-dark);
197. }
198. 
199. .btn-ghost {
200.   background: transparent;
