216. }
217. 
218. .btn-sm { padding: .45rem 1rem; font-size: .82rem; }
219. 
220. /* ============================================================
221.    HERO
222.    ============================================================ */
223. .hero {
224.   background: linear-gradient(135deg, #f0eeff 0%, #fff8f2 100%);
225.   overflow: hidden;
226. }
227. .hero-inner {
228.   max-width: var(--max-width);
229.   margin: 0 auto;
230.   padding: 5rem 1.5rem 4rem;
231.   display: grid;
232.   grid-template-columns: 1fr 1fr;
233.   align-items: center;
234.   gap: 3rem;
235. }
236. .hero-eyebrow {
237.   text-transform: uppercase;
238.   letter-spacing: .12em;
239.   font-size: .78rem;
240.   font-weight: 700;
241.   color: var(--color-brand);
242.   margin-bottom: .75rem;
243. }
244. .hero h1 {
245.   font-size: clamp(2rem, 4vw, 3.2rem);
246.   font-weight: 800;
247.   line-height: 1.15;
248.   letter-spacing: -.02em;
249.   margin-bottom: 1rem;
250.   color: var(--color-text);
251. }
252. .hero-sub {
253.   font-size: 1.05rem;
254.   color: var(--color-text-muted);
255.   max-width: 42ch;
256.   margin-bottom: 2rem;
257. }
258. .hero-ctas { display: flex; gap: 1rem; flex-wrap: wrap; }
259. 
260. /* Hero visual */
261. .hero-visual { position: relative; display: flex; justify-content: center; align-items: center; }
262. .hero-blob {
263.   position: absolute;
