506. }
507. .editorial-card:hover { box-shadow: var(--shadow-md); }
508. 
509. .editorial-img { height: 180px; }
510. .editorial-img--lead { height: 240px; }
511. 
512. .editorial-body { padding: 1.25rem; display: flex; flex-direction: column; gap: .5rem; flex: 1; }
513. 
514. .editorial-category {
515.   text-transform: uppercase;
516.   letter-spacing: .1em;
