 /* ============================================================
    LUMINA SHOP — styles.css
    Modern, clean retail design • WCAG 2.2 AA
    ============================================================ */

 /* ---- Reset / base ---- */
 *, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }

 :root {
   --color-brand:       #6C63FF;
   --color-brand-dark:  #4a42d0;
   --color-brand-light: #ede9ff;
   --color-text:        #1a1a2e;
   --color-text-muted:  #5a5a7a;
   --color-bg:          #ffffff;
   --color-surface:     #f7f7fb;
   --color-border:      #e2e2ec;
   --color-success:     #17705e;
   --color-error:       #c0392b;
   --color-deal-rose:   #fce4ec;
   --color-deal-teal:   #e0f7f5;
   --color-deal-indigo: #ede9ff;
   --radius-sm:  6px;
   --radius-md:  12px;
   --radius-lg:  20px;
   --shadow-sm:  0 1px 4px rgba(0,0,0,.08);
   --shadow-md:  0 4px 16px rgba(0,0,0,.10);
   --shadow-lg:  0 8px 32px rgba(0,0,0,.12);
   --font-sans:  'Segoe UI', system-ui, -apple-system, sans-serif;
   --transition: 200ms ease;
   --max-width:  1200px;
 }

 html { font-size: 16px; scroll-behavior: smooth; }

 body {
   font-family: var(--font-sans);
   color: var(--color-text);
   background: var(--color-bg);
   line-height: 1.6;
   -webkit-font-smoothing: antialiased;
 }

 /* ---- Utility ---- */
 .sr-only {
   position: absolute;
   width: 1px; height: 1px;
   padding: 0; margin: -1px;
   overflow: hidden;
   clip: rect(0,0,0,0);
   white-space: nowrap;
   border: 0;
 }

 /* ---- Skip link ---- */
 .skip-link {
   position: absolute;
   top: -3rem;
   left: 1rem;
   padding: .6rem 1.2rem;
   background: var(--color-brand);
   color: #fff;
   border-radius: var(--radius-sm);
   font-weight: 600;
   text-decoration: none;
   z-index: 9999;
   transition: top var(--transition);
 }
 .skip-link:focus { top: 1rem; }

 /* ---- Focus ring ---- */
 :focus-visible {
   outline: 3px solid var(--color-brand);
   outline-offset: 3px;
   border-radius: 2px;
 }
 /* Remove default for non-keyboard */
 :focus:not(:focus-visible) { outline: none; }

 /* ============================================================
    HEADER
    ============================================================ */
 .site-header {
   position: sticky;
   top: 0;
   z-index: 100;
   background: rgba(255,255,255,.92);
   backdrop-filter: blur(12px);
   border-bottom: 1px solid var(--color-border);
 }
 .header-inner {
   max-width: var(--max-width);
   margin: 0 auto;
   padding: 0 1.5rem;
   height: 64px;
   display: flex;
   align-items: center;
   gap: 2rem;
 }

 /* Logo */
 .logo {
   display: flex;
   align-items: center;
   gap: .5rem;
   text-decoration: none;
   color: var(--color-text);
   font-weight: 700;
   font-size: 1.2rem;
   flex-shrink: 0;
 }
 .logo--footer { color: #fff; }

 /* Primary nav */
 .nav-list {
   display: flex;
   list-style: none;
   gap: .25rem;
   flex: 1;
 }
 .nav-list a {
   display: block;
   padding: .4rem .75rem;
   text-decoration: none;
   color: var(--color-text-muted);
   font-size: .9rem;
   font-weight: 500;
   border-radius: var(--radius-sm);
   transition: color var(--transition), background var(--transition);
 }
 .nav-list a:hover,
 .nav-list a:focus-visible { color: var(--color-brand); background: var(--color-brand-light); }
 .nav-list a[aria-current="page"] {
   color: var(--color-brand);
   background: var(--color-brand-light);
   text-decoration: underline;
 }

 /* Header actions */
 .header-actions { display: flex; align-items: center; gap: .5rem; margin-left: auto; }

 .icon-btn {
   position: relative;
   display: flex;
   align-items: center;
   justify-content: center;
   width: 40px; height: 40px;
   background: transparent;
   border: none;
   border-radius: var(--radius-sm);
   color: var(--color-text);
   cursor: pointer;
   transition: background var(--transition), color var(--transition);
 }
 .icon-btn:hover { background: var(--color-surface); color: var(--color-brand); }

 .cart-count {
   position: absolute;
   top: 4px; right: 4px;
   width: 16px; height: 16px;
   background: var(--color-brand);
   color: #fff;
   font-size: .65rem;
   font-weight: 700;
   border-radius: 50%;
   display: flex; align-items: center; justify-content: center;
 }

 /* ============================================================
    BUTTONS
    ============================================================ */
 .btn {
   display: inline-flex;
   align-items: center;
   justify-content: center;
   gap: .4rem;
   padding: .65rem 1.4rem;
   border-radius: var(--radius-sm);
   font-size: .9rem;
   font-weight: 600;
   text-decoration: none;
   border: 2px solid transparent;
   cursor: pointer;
   transition: background var(--transition), color var(--transition), border-color var(--transition), transform var(--transition);
   white-space: nowrap;
 }
 .btn:active { transform: scale(.97); }

 .btn-primary {
   background: var(--color-brand);
   color: #fff;
   border-color: var(--color-brand);
 }
 .btn-primary:hover, .btn-primary:focus-visible {
   background: var(--color-brand-dark);
   border-color: var(--color-brand-dark);
 }

 .btn-ghost {
   background: transparent;
   color: var(--color-brand);
   border-color: var(--color-brand);
 }
 .btn-ghost:hover, .btn-ghost:focus-visible {
   background: var(--color-brand-light);
 }

 .btn-outline {
   background: transparent;
   color: var(--color-text);
   border-color: var(--color-border);
 }
 .btn-outline:hover, .btn-outline:focus-visible {
   border-color: var(--color-brand);
   color: var(--color-brand);
 }

 .btn-sm { padding: .45rem 1rem; font-size: .82rem; }

 /* ============================================================
    HERO
    ============================================================ */
 .hero {
   background: linear-gradient(135deg, #f0eeff 0%, #fff8f2 100%);
   overflow: hidden;
 }
 .hero-inner {
   max-width: var(--max-width);
   margin: 0 auto;
   padding: 5rem 1.5rem 4rem;
   display: grid;
   grid-template-columns: 1fr 1fr;
   align-items: center;
   gap: 3rem;
 }
 .hero-eyebrow {
   text-transform: uppercase;
   letter-spacing: .12em;
   font-size: .78rem;
   font-weight: 700;
   color: var(--color-brand);
   margin-bottom: .75rem;
 }
 .hero h1 {
   font-size: clamp(2rem, 4vw, 3.2rem);
   font-weight: 800;
   line-height: 1.15;
   letter-spacing: -.02em;
   margin-bottom: 1rem;
   color: var(--color-text);
 }
 .hero-sub {
   font-size: 1.05rem;
   color: var(--color-text-muted);
   max-width: 42ch;
   margin-bottom: 2rem;
 }
 .hero-ctas { display: flex; gap: 1rem; flex-wrap: wrap; }

 /* Hero visual */
 .hero-visual { position: relative; display: flex; justify-content: center; align-items: center; }
 .hero-blob {
   position: absolute;
   width: 360px; height: 360px;
   background: radial-gradient(circle at 40% 40%, #c4beff 0%, #a89cff 60%, transparent 100%);
   border-radius: 50%;
   opacity: .45;
 }
 .hero-card-mockup {
   position: relative;
   z-index: 1;
   background: #fff;
   border-radius: var(--radius-lg);
   box-shadow: var(--shadow-lg);
   padding: 1rem;
   width: 220px;
 }
 .mockup-img-placeholder {
   width: 100%; height: 160px;
   background: linear-gradient(135deg, #e0daff 0%, #c9bfff 100%);
   border-radius: var(--radius-md);
   margin-bottom: 1rem;
 }
 .mockup-lines { display: flex; flex-direction: column; gap: .5rem; }
 .mockup-line { height: 10px; background: var(--color-border); border-radius: 4px; }
 .mockup-line.long { width: 80%; }
 .mockup-line.short { width: 50%; }

 /* ============================================================
    PROMO BANNER
    ============================================================ */
 .promo-banner {
   background: var(--color-text);
   color: #fff;
   text-align: center;
   padding: .7rem 1.5rem;
   display: flex;
   align-items: center;
   justify-content: center;
   gap: 1rem;
   font-size: .88rem;
 }
 .promo-dismiss {
   background: transparent;
   border: none;
   color: rgba(255,255,255,.75);
   cursor: pointer;
   display: flex;
   align-items: center;
   padding: .25rem;
   border-radius: var(--radius-sm);
   flex-shrink: 0;
   transition: color var(--transition);
 }
 .promo-dismiss:hover { color: #fff; }

 /* ============================================================
    SHARED SECTION STYLES
    ============================================================ */
 .section-inner {
   max-width: var(--max-width);
   margin: 0 auto;
   padding: 4rem 1.5rem;
 }
 .section-header {
   display: flex;
   align-items: baseline;
   justify-content: space-between;
   margin-bottom: 2rem;
   flex-wrap: wrap;
   gap: .5rem;
 }
 .section-header h2 {
   font-size: clamp(1.4rem, 3vw, 1.9rem);
   font-weight: 800;
   letter-spacing: -.02em;
 }
 .view-all {
   font-size: .85rem;
   font-weight: 600;
   color: var(--color-brand);
   text-decoration: none;
   white-space: nowrap;
 }
 .view-all:hover, .view-all:focus-visible { text-decoration: underline; }

 /* ============================================================
    PRODUCT GRID
    ============================================================ */
 .products-section { background: var(--color-bg); }

 .product-grid {
   list-style: none;
   display: grid;
   grid-template-columns: repeat(auto-fill, minmax(240px, 1fr));
   gap: 1.5rem;
 }

 .product-card {
   position: relative;
   background: var(--color-surface);
   border-radius: var(--radius-md);
   overflow: hidden;
   transition: box-shadow var(--transition), transform var(--transition);
 }
 .product-card:hover { box-shadow: var(--shadow-md); transform: translateY(-2px); }
 .product-card--highlighted { background: var(--color-brand-light); }

 .badge {
   position: absolute;
   top: .75rem; left: .75rem;
   background: var(--color-brand);
   color: #fff;
   font-size: .7rem;
   font-weight: 700;
   padding: .25rem .6rem;
   border-radius: 100px;
   text-transform: uppercase;
   letter-spacing: .06em;
   z-index: 1;
 }

 .product-img-link { display: block; }
 .product-img {
   width: 100%;
   height: 200px;
   transition: transform var(--transition);
 }
 .product-card:hover .product-img { transform: scale(1.02); }

 .product-info { padding: 1rem; }

 .product-name {
   text-decoration: none;
   color: inherit;
   display: block;
   margin-bottom: .3rem;
 }
 .product-name h3 {
   font-size: 1rem;
   font-weight: 700;
   line-height: 1.3;
 }
 .product-name:hover h3,
 .product-name:focus-visible h3 { color: var(--color-brand); }

 .product-meta {
   font-size: .8rem;
   color: var(--color-text-muted);
   margin-bottom: .75rem;
 }
 .product-footer {
   display: flex;
   align-items: center;
   justify-content: space-between;
   gap: .5rem;
 }
 .product-price {
   font-size: 1.05rem;
   font-weight: 700;
   color: var(--color-text);
 }

 /* ============================================================
    DEALS
    ============================================================ */
 .deals-section { background: var(--color-surface); }

 .deals-grid {
   list-style: none;
   display: grid;
   grid-template-columns: 2fr 1fr 1fr;
   gap: 1.5rem;
 }

 .deal-card {
   background: var(--color-bg);
   border-radius: var(--radius-md);
   overflow: hidden;
   box-shadow: var(--shadow-sm);
   display: flex;
   flex-direction: column;
   transition: box-shadow var(--transition);
 }
 .deal-card:hover { box-shadow: var(--shadow-md); }

 .deal-visual { height: 200px; flex-shrink: 0; }
 .deal-visual--indigo { background: linear-gradient(135deg, #c4beff 0%, #9d93ff 100%); }
 .deal-visual--rose   { background: linear-gradient(135deg, #fce4ec 0%, #f48fb1 100%); }
 .deal-visual--teal   { background: linear-gradient(135deg, #b2dfdb 0%, #4db6ac 100%); }

 .deal-body { padding: 1.25rem; display: flex; flex-direction: column; gap: .75rem; flex: 1; }
 .deal-body--sm { padding: 1rem; gap: .5rem; }

 .deal-tag {
   text-transform: uppercase;
   letter-spacing: .1em;
   font-size: .7rem;
   font-weight: 700;
   color: var(--color-brand);
 }
 .deal-title {
   font-size: 1.2rem;
   font-weight: 700;
   line-height: 1.3;
 }
 .deal-desc { font-size: .88rem; color: var(--color-text-muted); }

 .deal-discount {
   display: flex;
   align-items: center;
   gap: .6rem;
   flex-wrap: wrap;
 }
 .price-was { color: var(--color-text-muted); font-size: .9rem; }
 .price-was s { text-decoration: line-through; }
 .price-now { font-size: 1.2rem; font-weight: 800; color: var(--color-text); }
 .discount-badge {
   background: #e8f5e9;
   color: #2e7d32;
   font-size: .75rem;
   font-weight: 700;
   padding: .2rem .55rem;
   border-radius: 100px;
 }

 /* ============================================================
    EDITORIAL
    ============================================================ */
 .editorial-section { background: var(--color-bg); }

 .editorial-grid {
   list-style: none;
   display: grid;
   grid-template-columns: 1fr 1fr 1fr;
   gap: 1.5rem;
 }

 .editorial-card {
   border-radius: var(--radius-md);
   overflow: hidden;
   background: var(--color-surface);
   display: flex;
   flex-direction: column;
   transition: box-shadow var(--transition);
 }
 .editorial-card:hover { box-shadow: var(--shadow-md); }

 .editorial-img { height: 180px; }
 .editorial-img--lead { height: 240px; }

 .editorial-body { padding: 1.25rem; display: flex; flex-direction: column; gap: .5rem; flex: 1; }

 .editorial-category {
   text-transform: uppercase;
   letter-spacing: .1em;
   font-size: .7rem;
   font-weight: 700;
   color: var(--color-brand);
 }
 .editorial-card h3 {
   font-size: 1.05rem;
   font-weight: 700;
   line-height: 1.35;
 }
 .editorial-link {
   color: var(--color-text);
