   ============================================================ */

/* ---- Reset / base ---- */
*, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }

:root {
  --color-brand:       #4f46e5;
  --color-brand-dark:  #3730a3;
  --color-brand-light: #ede9ff;
  --color-text:        #1a1a2e;
  --color-text-muted:  #5a5a7a;
  --color-bg:          #ffffff;
  --color-surface:     #f7f7fb;
  --color-border:      #e2e2ec;
  --color-success:     #17705e;
  --color-error:       #c0392b;
  --color-deal-rose:   #fce4ec;
  --color-deal-teal:   #e0f7f5;
  --color-deal-indigo: #ede9ff;
  --radius-sm:  6px;
  --radius-md:  12px;
  --radius-lg:  20px;
  --shadow-sm:  0 1px 4px rgba(0,0,0,.08);
  --shadow-md:  0 4px 16px rgba(0,0,0,.10);
  --shadow-lg:  0 8px 32px rgba(0,0,0,.12);
  --font-sans:  'Segoe UI', system-ui, -apple-system, sans-serif;
  --transition: 200ms ease;
  --max-width:  1200px;
}

html { font-size: 16px; scroll-behavior: smooth; }

body {
  font-family: var(--font-sans);
  color: var(--color-text);
  background: var(--color-bg);
  line-height: 1.6;
  -webkit-font-smoothing: antialiased;
}

/* ---- Utility ---- */
.sr-only {
  position: absolute;
  width: 1px; height: 1px;
  padding: 0; margin: -1px;
  overflow: hidden;
  clip: rect(0,0,0,0);
  white-space: nowrap;
  border: 0;
}

/* ---- Skip link ---- */
.skip-link {
  position: absolute;
  top: -3rem;
  left: 1rem;
  padding: .6rem 1.2rem;
  background: var(--color-brand);
  color: #fff;
  border-radius: var(--radius-sm);
  font-weight: 600;
  text-decoration: none;
  z-index: 9999;
  transition: top var(--transition);
}
.skip-link:focus { top: 1rem; }

/* ---- Focus ring ---- */
:focus-visible {
  outline: 3px solid var(--color-brand);
  outline-offset: 3px;
  border-radius: 2px;
}
/* Remove default for non-keyboard */
:focus:not(:focus-visible) { outline: none; }

/* ============================================================
   HEADER
   ============================================================ */
.site-header {
  position: sticky;
  top: 0;
  z-index: 100;
  background: rgba(255,255,255,.92);
  backdrop-filter: blur(12px);
  border-bottom: 1px solid var(--color-border);
}
.header-inner {
  max-width: var(--max-width);
  margin: 0 auto;
  padding: 0 1.5rem;
  height: 64px;
  display: flex;
  align-items: center;
  gap: 2rem;
}

/* Logo */
.logo {
  display: flex;
  align-items: center;
  gap: .5rem;
  text-decoration: none;
  color: var(--color-text);
  font-weight: 700;
  font-size: 1.2rem;
  flex-shrink: 0;
}
.logo--footer { color: #fff; }

/* Primary nav */
.nav-list {
  display: flex;
  list-style: none;
  gap: .25rem;
  flex: 1;
}
.nav-list a {
  display: block;
  padding: .4rem .75rem;
  text-decoration: none;
  color: var(--color-text-muted);
  font-size: .9rem;
  font-weight: 500;
  border-radius: var(--radius-sm);
  transition: color var(--transition), background var(--transition);
}
.nav-list a:hover,
.nav-list a:focus-visible { color: var(--color-brand); background: var(--color-brand-light); }
.nav-list a[aria-current="page"] {
  color: var(--color-brand);
  background: var(--color-brand-light);
  text-decoration: underline;
}

/* Header actions */
.header-actions { display: flex; align-items: center; gap: .5rem; margin-left: auto; }

.icon-btn {
  position: relative;
  display: flex;
  align-items: center;
  justify-content: center;
  width: 40px; height: 40px;
  background: transparent;
  border: none;
  border-radius: var(--radius-sm);
  color: var(--color-text);
  cursor: pointer;
  transition: background var(--transition), color var(--transition);
}
.icon-btn:hover { background: var(--color-surface); color: var(--color-brand); }

.cart-count {
  position: absolute;
  top: 4px; right: 4px;
  width: 16px; height: 16px;
  background: var(--color-brand);
  color: #fff;
  font-size: .65rem;
  font-weight: 700;
  border-radius: 50%;
  display: flex; align-items: center; justify-content: center;
}

/* ============================================================
   BUTTONS
   ============================================================ */
.btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: .4rem;
  padding: .65rem 1.4rem;
  border-radius: var(--radius-sm);
  font-size: .9rem;
  font-weight: 600;
  text-decoration: none;
  border: 2px solid transparent;
  cursor: pointer;
  transition: background var(--transition), color var(--transition), border-color var(--transition), transform var(--transition);
  white-space: nowrap;
}
.btn:active { transform: scale(.97); }

.btn-primary {
  background: var(--color-brand);
  color: #fff;
  border-color: var(--color-brand);
}
.btn-primary:hover, .btn-primary:focus-visible {
  background: var(--color-brand-dark);
  border-color: var(--color-brand-dark);
}

.btn-ghost {
  background: transparent;
  color: var(--color-brand);
  border-color: var(--color-brand);
}
.btn-ghost:hover, .btn-ghost:focus-visible {
  background: var(--color-brand-light);
}

.btn-outline {
  background: transparent;
  color: var(--color-text);
  border-color: var(--color-border);
}
.btn-outline:hover, .btn-outline:focus-visible {
  border-color: var(--color-brand);
  color: var(--color-brand);
}

.btn-sm { padding: .45rem 1rem; font-size: .82rem; }

/* ============================================================
   HERO
   ============================================================ */
.hero {
  background: linear-gradient(135deg, #f0eeff 0%, #fff8f2 100%);
  overflow: hidden;
}
.hero-inner {
  max-width: var(--max-width);
  margin: 0 auto;
  padding: 5rem 1.5rem 4rem;
  display: grid;
  grid-template-columns: 1fr 1fr;
  align-items: center;
  gap: 3rem;
}
.hero-eyebrow {
