  margin: 0 auto;
  padding: 4rem 1.5rem;
}
.section-header {
  display: flex;
  align-items: baseline;
  justify-content: space-between;
  margin-bottom: 2rem;
  flex-wrap: wrap;
  gap: .5rem;
}
.section-header h2 {
