  font-weight: 700;
  color: var(--color-text);
}

/* ============================================================
   DEALS
   ============================================================ */
.deals-section { background: var(--color-surface); }

.deals-grid {
  list-style: none;
  display: grid;
  grid-template-columns: 2fr 1fr 1fr;
  gap: 1.5rem;
}

.deal-card {
  background: var(--color-bg);
  border-radius: var(--radius-md);
  overflow: hidden;
  box-shadow: var(--shadow-sm);
  display: flex;
  flex-direction: column;
  transition: box-shadow var(--transition);
}
.deal-card:hover { box-shadow: var(--shadow-md); }

.deal-visual { height: 200px; flex-shrink: 0; }
.deal-visual--indigo { background: linear-gradient(135deg, #c4beff 0%, #9d93ff 100%); }
.deal-visual--rose   { background: linear-gradient(135deg, #fce4ec 0%, #f48fb1 100%); }
.deal-visual--teal   { background: linear-gradient(135deg, #b2dfdb 0%, #4db6ac 100%); }

.deal-body { padding: 1.25rem; display: flex; flex-direction: column; gap: .75rem; flex: 1; }
.deal-body--sm { padding: 1rem; gap: .5rem; }

.deal-tag {
  text-transform: uppercase;
  letter-spacing: .1em;
  font-size: .7rem;
  font-weight: 700;
  color: var(--color-brand);
}
.deal-title {
  font-size: 1.2rem;
  font-weight: 700;
  line-height: 1.3;
}
.deal-desc { font-size: .88rem; color: var(--color-text-muted); }

.deal-discount {
  display: flex;
  align-items: center;
  gap: .6rem;
  flex-wrap: wrap;
}
.price-was { color: var(--color-text-muted); font-size: .9rem; }
.price-was s { text-decoration: line-through; }
.price-now { font-size: 1.2rem; font-weight: 800; color: var(--color-text); }
.discount-badge {
  background: #e8f5e9;
  color: #2e7d32;
  font-size: .75rem;
  font-weight: 700;
  padding: .2rem .55rem;
  border-radius: 100px;
}

/* ============================================================
   EDITORIAL
   ============================================================ */
.editorial-section { background: var(--color-bg); }

.editorial-grid {
  list-style: none;
  display: grid;
  grid-template-columns: 1fr 1fr 1fr;
  gap: 1.5rem;
}

.editorial-card {
  border-radius: var(--radius-md);
  overflow: hidden;
  background: var(--color-surface);
  display: flex;
  flex-direction: column;
  transition: box-shadow var(--transition);
}
.editorial-card:hover { box-shadow: var(--shadow-md); }

.editorial-img { height: 180px; }
.editorial-img--lead { height: 240px; }

.editorial-body { padding: 1.25rem; display: flex; flex-direction: column; gap: .5rem; flex: 1; }

.editorial-category {
  text-transform: uppercase;
  letter-spacing: .1em;
  font-size: .7rem;
  font-weight: 700;
  color: var(--color-brand);
}
.editorial-card h3 {
  font-size: 1.05rem;
  font-weight: 700;
  line-height: 1.35;
}
.editorial-link {
  color: var(--color-text);
  text-decoration: none;
}
.editorial-link:hover, .editorial-link:focus-visible { color: var(--color-brand); text-decoration: underline; }

.editorial-card p { font-size: .88rem; color: var(--color-text-muted); }
.editorial-read-time { font-size: .78rem; color: var(--color-text-muted); font-weight: 600; margin-top: auto; }

/* ============================================================
   NEWSLETTER
   ============================================================ */
.newsletter-section { background: var(--color-brand); }
.newsletter-section .section-inner { padding: 3.5rem 1.5rem; }

.newsletter-inner {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 2rem;
  flex-wrap: wrap;
}
.newsletter-text h2 {
  font-size: clamp(1.4rem, 3vw, 2rem);
  font-weight: 800;
  color: #fff;
  letter-spacing: -.02em;
  margin-bottom: .4rem;
}
.newsletter-text p { color: #fff; font-size: .95rem; }

.newsletter-form {
  display: flex;
  gap: .75rem;
  flex-wrap: wrap;
  align-items: flex-start;
  flex-shrink: 0;
}
.form-group { display: flex; flex-direction: column; }
.email-input {
  padding: .65rem 1rem;
  border: 2px solid rgba(255,255,255,.4);
  border-radius: var(--radius-sm);
  background: rgba(255,255,255,.1);
  color: #fff;
  font-size: .9rem;
  width: 260px;
  transition: border-color var(--transition), background var(--transition);
}
.email-input::placeholder { color: rgba(255,255,255,.6); }
.email-input:focus-visible {
  outline: 3px solid #fff;
  outline-offset: 2px;
  border-color: #fff;
  background: rgba(255,255,255,.22);
}
.newsletter-form .btn-primary {
  background: #fff;
  color: var(--color-brand);
  border-color: #fff;
}
.newsletter-form .btn-primary:hover,
.newsletter-form .btn-primary:focus-visible {
  background: var(--color-brand-light);
  border-color: var(--color-brand-light);
}

.newsletter-status { font-size: .85rem; color: #fff; min-height: 1.2em; width: 100%; }

/* ============================================================
   FOOTER
   ============================================================ */
.site-footer { background: #12122a; color: #b0b0cc; }

.footer-inner {
  max-width: var(--max-width);
  margin: 0 auto;
  padding: 3.5rem 1.5rem 2rem;
  display: grid;
  grid-template-columns: 2fr 1fr 1fr 1fr;
  gap: 2.5rem;
}

.footer-tagline { font-size: .85rem; margin-top: .6rem; color: #7070a0; }

.footer-nav-heading {
  font-size: .78rem;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: .1em;
  color: #fff;
  margin-bottom: 1rem;
}
nav[aria-label="Shop"] ul,
nav[aria-label="Company"] ul,
nav[aria-label="Support"] ul {
  list-style: none;
  display: flex;
  flex-direction: column;
  gap: .6rem;
}
nav[aria-label="Shop"] a,
nav[aria-label="Company"] a,
nav[aria-label="Support"] a {
  color: #b0b0cc;
  text-decoration: none;
  font-size: .88rem;
  transition: color var(--transition);
}
nav[aria-label="Shop"] a:hover,
nav[aria-label="Company"] a:hover,
nav[aria-label="Support"] a:hover,
nav[aria-label="Shop"] a:focus-visible,
nav[aria-label="Company"] a:focus-visible,
nav[aria-label="Support"] a:focus-visible { color: #fff; }

.footer-bottom {
  border-top: 1px solid #2a2a4a;
  max-width: var(--max-width);
  margin: 0 auto;
  padding: 1.5rem 1.5rem;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 1rem;
  flex-wrap: wrap;
}
.copyright { font-size: .82rem; color: #7070a0; }
.legal-links {
  list-style: none;
  display: flex;
  gap: 1.25rem;
  flex-wrap: wrap;
}
.legal-links a {
  color: #7070a0;
  text-decoration: none;
  font-size: .82rem;
  transition: color var(--transition);
}
.legal-links a:hover, .legal-links a:focus-visible { color: #fff; }

/* ============================================================
   FORCED COLORS (Windows High Contrast)
   ============================================================ */
@media (forced-colors: active) {
  .btn { border: 2px solid ButtonText; }
  .product-card, .deal-card, .editorial-card { border: 1px solid ButtonText; }
  .hero-blob, .mockup-img-placeholder,
  .deal-visual, .editorial-img { forced-color-adjust: none; background: Canvas; }
  .badge, .discount-badge, .deal-tag, .editorial-category { forced-color-adjust: none; }
  .promo-banner { border-bottom: 1px solid ButtonText; }
  .site-header { border-bottom: 1px solid ButtonText; }
}

/* ============================================================
   REDUCED MOTION
   ============================================================ */
@media (prefers-reduced-motion: reduce) {
  *, *::before, *::after { transition: none !important; animation: none !important; }
  html { scroll-behavior: auto; }
  .product-card:hover, .deal-card:hover, .editorial-card:hover { transform: none; }
  .product-card:hover .product-img { transform: none; }
}

/* ============================================================
   RESPONSIVE — 320 px reflow
   ============================================================ */
@media (max-width: 900px) {
  .hero-inner { grid-template-columns: 1fr; text-align: center; padding: 3rem 1.5rem; }
  .hero-visual { display: none; }
  .hero-ctas { justify-content: center; }
  .deals-grid { grid-template-columns: 1fr 1fr; }
  .footer-inner { grid-template-columns: 1fr 1fr; }
}

@media (max-width: 640px) {
  .nav-list { display: none; } /* mobile nav would need a hamburger; hidden for now */
  .deals-grid { grid-template-columns: 1fr; }
  .editorial-grid { grid-template-columns: 1fr; }
  .newsletter-inner { flex-direction: column; }
  .newsletter-form { flex-direction: column; width: 100%; }
  .email-input { width: 100%; }
  .footer-inner { grid-template-columns: 1fr; }
  .section-inner { padding: 2.5rem 1rem; }
}

@media (max-width: 400px) {
  .hero h1 { font-size: 1.7rem; }
  .product-grid { grid-template-columns: 1fr; }
}
