.price-now { font-size: 1.2rem; font-weight: 800; color: var(--color-text); }
.discount-badge {
  background: #e8f5e9;
  color: #2e7d32;
  font-size: .75rem;
  font-weight: 700;
  padding: .2rem .55rem;
  border-radius: 100px;
}

/* ============================================================
