  grid-template-columns: 2fr 1fr 1fr 1fr;
  gap: 2.5rem;
}

.footer-tagline { font-size: .85rem; margin-top: .6rem; color: #9090b8; }

.footer-nav-heading {
  font-size: .78rem;
