  background: var(--color-bg);
  line-height: 1.6;
  -webkit-font-smoothing: antialiased;
}

/* ---- Utility ---- */
.sr-only {
  position: absolute;
  width: 1px; height: 1px;
  padding: 0; margin: -1px;
  overflow: hidden;
  clip: rect(0,0,0,0);
  white-space: nowrap;
  border: 0;
}

/* ---- Skip link ---- */
.skip-link {
  position: absolute;
  top: -3rem;
  left: 1rem;
  padding: .6rem 1.2rem;
  background: var(--color-brand);
  color: #fff;
  border-radius: var(--radius-sm);
  font-weight: 600;
